"""BPPM generation and cache management for m5C-SSNet."""

import fcntl
import glob
import hashlib
import os
import re
import shutil
import subprocess
import tempfile

import numpy as np
import torch

from utils.runtime import _extract_center_window

def _locate_rnafold_dotplot(workdir):
    """Return the dot-plot file generated by RNAfold."""
    candidates = []
    for pattern in ("*dp.ps", "dot.ps", "*.ps"):
        candidates.extend(glob.glob(os.path.join(workdir, pattern)))

    for path in dict.fromkeys(candidates):
        filename = os.path.basename(path)
        if filename.endswith("dp.ps") or filename == "dot.ps":
            return path
    return None

def compute_bppm_with_rnafold(sequence):
    """Compute a base-pair probability matrix with the RNAfold executable."""
    rnafold_executable = shutil.which("RNAfold")
    if rnafold_executable is None:
        raise RuntimeError(
            "RNAfold was not found. Install ViennaRNA or provide a valid "
            "precomputed BPPM cache."
        )

    rna_sequence = str(sequence).upper().replace("T", "U")
    sequence_length = len(rna_sequence)
    bppm = np.zeros((sequence_length, sequence_length), dtype=np.float32)

    with tempfile.TemporaryDirectory(prefix="m5c_ssnet_bppm_") as workdir:
        completed = subprocess.run(
            [rnafold_executable, "-p"],
            input=f"{rna_sequence}\n",
            text=True,
            capture_output=True,
            check=True,
            cwd=workdir,
        )
        dotplot_path = _locate_rnafold_dotplot(workdir)
        if dotplot_path is None:
            raise RuntimeError(
                "RNAfold did not generate a dot-plot file.\n"
                f"stdout:\n{completed.stdout}\n"
                f"stderr:\n{completed.stderr}"
            )

        pattern = re.compile(r"^\s*(\d+)\s+(\d+)\s+([0-9eE.+-]+)\s+ubox\s*$")
        with open(dotplot_path, "r", encoding="utf-8", errors="ignore") as handle:
            for raw_line in handle:
                match = pattern.match(raw_line.strip())
                if match is None:
                    continue
                left = int(match.group(1)) - 1
                right = int(match.group(2)) - 1
                probability = float(match.group(3)) ** 2
                if 0 <= left < sequence_length and 0 <= right < sequence_length:
                    bppm[left, right] = probability
                    bppm[right, left] = probability

    return bppm

def _canonical_cache_path(dataset_path, cache_dir, input_length):
    absolute_path = os.path.abspath(dataset_path)
    digest = hashlib.md5(absolute_path.encode("utf-8")).hexdigest()[:8]
    dataset_name = os.path.splitext(os.path.basename(dataset_path))[0]
    return os.path.join(
        cache_dir, f"{dataset_name}.bppm{input_length}.{digest}.pt"
    )

def _cache_candidates(dataset_path, cache_dir, input_length):
    canonical_path = _canonical_cache_path(dataset_path, cache_dir, input_length)
    dataset_name = os.path.splitext(os.path.basename(dataset_path))[0]
    pattern = os.path.join(cache_dir, f"{dataset_name}.bppm{input_length}.*.pt")
    candidates = [canonical_path]
    candidates.extend(path for path in sorted(glob.glob(pattern)) if path != canonical_path)
    return canonical_path, candidates

def _load_valid_cache(cache_path, centered_sequences, input_length):
    if not os.path.isfile(cache_path):
        return None
    try:
        payload = torch.load(cache_path, map_location="cpu", weights_only=False)
    except (OSError, RuntimeError, TypeError, ValueError):
        return None

    if not isinstance(payload, dict):
        return None
    cached_sequences = payload.get("sequences")
    cached_bppm = payload.get("bppm")
    cached_length = int(payload.get("input_len", -1))
    expected_shape = (len(centered_sequences), input_length, input_length)
    if (
        cached_sequences != centered_sequences
        or not torch.is_tensor(cached_bppm)
        or tuple(cached_bppm.shape) != expected_shape
        or cached_length != input_length
    ):
        return None
    return cached_bppm.to(torch.float32)

def load_or_build_bppm_cache(
    sequences,
    dataset_path,
    cache_dir,
    input_length=41,
    log=print,
):
    """Load a matching BPPM cache or build a new cache without overwriting old data."""
    input_length = int(input_length)
    os.makedirs(cache_dir, exist_ok=True)
    centered_sequences = [
        _extract_center_window(sequence, target_len=input_length)
        for sequence in sequences
    ]
    canonical_path, candidates = _cache_candidates(
        dataset_path, cache_dir, input_length
    )

    for candidate in candidates:
        cached_bppm = _load_valid_cache(
            candidate, centered_sequences, input_length
        )
        if cached_bppm is not None:
            log(f"Using BPPM cache: {candidate}")
            return cached_bppm

    lock_path = f"{canonical_path}.lock"
    with open(lock_path, "a+", encoding="utf-8") as lock_file:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX)
        cached_bppm = _load_valid_cache(
            canonical_path, centered_sequences, input_length
        )
        if cached_bppm is not None:
            log(f"Using BPPM cache: {canonical_path}")
            return cached_bppm

        log(f"Building BPPM cache: {canonical_path}")
        matrices = []
        total = len(centered_sequences)
        for index, sequence in enumerate(centered_sequences, start=1):
            if index == 1 or index % 200 == 0 or index == total:
                log(f"Computing BPPM: {index}/{total}")
            matrix = compute_bppm_with_rnafold(sequence)
            matrices.append(torch.from_numpy(matrix))

        bppm = torch.stack(matrices, dim=0).to(torch.float32)
        payload = {
            "sequences": centered_sequences,
            "bppm": bppm,
            "input_len": input_length,
        }
        temporary_path = f"{canonical_path}.tmp.{os.getpid()}"
        try:
            torch.save(payload, temporary_path)
            os.replace(temporary_path, canonical_path)
        finally:
            if os.path.exists(temporary_path):
                os.remove(temporary_path)
        log(f"Saved BPPM cache: {canonical_path}")
        return bppm
